const target = $('Note Who Wrote and When').first().json;
const rows = $input.all().map(i => i.json);
const row = rows.find(r => String(r.messageId || '') === String(target.messageId));
const answered = Boolean(row && String(row.status || '').toLowerCase() === 'answered');
return [{ json: { ...target, answered, rowFound: Boolean(row) } }];
